"use client";

import Link from "next/link";
import { useMemo, useState } from "react";
import { Archive, Check, Copy, Eye, EyeOff, ExternalLink, FileDown, FileUp, Layers3, MoreHorizontal, Palette, Pencil, Plus, Search, Sparkles, Trash2, UtensilsCrossed } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Card } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { Label } from "@/components/ui/label";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Tabs, TabsContent, TabsList, TabsTrigger, Checkbox, Switch } from "@/components/ui/controls";
import { PageHeader, EmptyState, FormField, SectionHeading } from "@/components/ui/layout-blocks";
import { cn } from "@/lib/utils";
import { saveCategoryAction, deleteCategoryAction, toggleCategoryAction, duplicateCategoryAction, saveProductAction, deleteProductAction, toggleProductAction, duplicateProductAction, setProductAvailabilityAction, saveModifierGroupAction, deleteModifierGroupAction, toggleModifierOptionAction, saveExtraAction, deleteExtraAction, toggleExtraAction, saveMenuAction, duplicateMenuAction, setMenuStatusAction, saveMenuThemeAction, resetMenuThemeAction, importProductsCsvAction, uploadProductImageAction, reorderMenuItemsAction, bulkProductAction } from "@/app/actions/menu";

type Locale = "ar" | "en";
type Category = { id: string; menuId: string | null; nameAr: string; nameEn: string | null; description: string | null; imageUrl: string | null; coverUrl: string | null; sortOrder: number; isVisible: boolean; availableFrom: Date | string | null; availableTo: Date | string | null; createdAt: string; updatedAt: string; _count: { products: number } };
type Group = { id: string; nameAr: string; nameEn: string | null; description: string | null; isRequired: boolean; minSelect: number; maxSelect: number; isMultiple: boolean; sortOrder: number; createdAt: string; updatedAt: string; _count: { products: number }; options: { id: string; nameAr: string; nameEn: string | null; priceDelta: string; isDefault: boolean; isAvailable: boolean; sortOrder: number }[] };
type Extra = { id: string; nameAr: string; nameEn: string | null; price: string; isActive: boolean; sortOrder: number; createdAt: string; _count: { products: number } };
type Product = { id: string; categoryId: string | null; nameAr: string; nameEn: string | null; descriptionAr: string | null; descriptionEn: string | null; sku: string | null; price: string; compareAtPrice: string | null; costPrice: string | null; taxRate: string; imageUrl: string | null; calories: number | null; prepMinutes: number; ingredients: string | null; allergens: string[]; tags: string[]; availability: string; stockQty: number | null; trackStock: boolean; isVisible: boolean; isFeatured: boolean; sortOrder: number; createdAt: string; updatedAt: string; modifierGroups: { groupId: string; group: Omit<Group, "_count"> }[]; extras: { extraId: string; extra: Omit<Extra, "_count"> }[] };
type Menu = { id: string; name: string; description: string | null; type: string; status: string; isDefault: boolean; startsAt: string | null; endsAt: string | null; createdAt: string; updatedAt: string; _count: { schedules: number } };

const copy = (locale: Locale, ar: string, en: string) => locale === "ar" ? ar : en;
const money = (value: string | number, currency: string) => `${Number(value).toFixed(2)} ${currency}`;

function ActionForm({ action, children, hidden = {}, confirmText }: { action: (form: FormData) => void; children: React.ReactNode; hidden?: Record<string, string>; confirmText?: string }) {
  return <form action={action} onSubmit={(event) => { if (confirmText && !window.confirm(confirmText)) event.preventDefault(); }} className="inline-flex">{Object.entries(hidden).map(([key, value]) => <input key={key} type="hidden" name={key} value={value} />)}{children}</form>;
}

export function MenuWorkspace({ locale, activeTab, permissions, isOwner, restaurant, categories, products, groups, extras, menus }: { locale: Locale; activeTab: string; permissions: string[]; isOwner: boolean; restaurant: { slug: string; name: string; currency: string; menuTheme: unknown; primaryColor: string; secondaryColor: string; fontFamily: string; menuLayout: string }; categories: Category[]; products: Product[]; groups: Group[]; extras: Extra[]; menus: Menu[] }) {
  const can = (permission: string) => isOwner || permissions.includes(permission);
  const [query, setQuery] = useState("");
  const [categoryId, setCategoryId] = useState("all");
  const [editingCategory, setEditingCategory] = useState<Category | null>(null);
  const [editingProduct, setEditingProduct] = useState<Product | null>(null);
  const [editingGroup, setEditingGroup] = useState<Group | null>(null);
  const [editingExtra, setEditingExtra] = useState<Extra | null>(null);
  const [editingMenu, setEditingMenu] = useState<Menu | null>(null);
  const theme = (restaurant.menuTheme ?? {}) as Record<string, string | boolean>;
  const filteredProducts = useMemo(() => products.filter((p) => (categoryId === "all" || p.categoryId === categoryId) && (!query || `${p.nameAr} ${p.nameEn ?? ""} ${p.sku ?? ""}`.toLowerCase().includes(query.toLowerCase()))), [products, query, categoryId]);
  const filteredCategories = categories.filter((c) => !query || `${c.nameAr} ${c.nameEn ?? ""}`.toLowerCase().includes(query.toLowerCase()));
  const base = "/app/menu";
  const tab = ["categories", "products", "groups", "extras", "design", "seasonal", "preview"].includes(activeTab) ? activeTab : "overview";

  return <div className="space-y-6">
    <PageHeader title={copy(locale, "إدارة المنيو", "Menu management")} description={copy(locale, "ابنِ منيو واضحاً وقابلاً للنشر، مع تحكم كامل بالمنتجات والخيارات والتصميم.", "Build a clear, publishable menu with complete control over products, options, and design.")} breadcrumbs={[{ label: copy(locale, "الرئيسية", "Home"), href: "/app/dashboard" }, { label: copy(locale, "إدارة المنيو", "Menu management") }]} actions={<div className="flex flex-wrap gap-2"><Button asChild variant="outline" size="sm"><Link href={`/r/${restaurant.slug}`} target="_blank"><ExternalLink />{copy(locale, "عرض المنيو العام", "View public menu")}</Link></Button>{can("menu.products.create") ? <Button asChild size="sm"><Link href={`${base}/products?new=1`}><Plus />{copy(locale, "إضافة منتج", "Add product")}</Link></Button> : null}</div>} />
    <Card className="overflow-hidden"><div className="border-b bg-muted/30 p-3"><Tabs value={tab} onValueChange={(value) => { window.location.href = `${base}/${value === "overview" ? "" : value}`; }}><TabsList className="h-auto w-full flex-wrap justify-start gap-1 bg-transparent p-0"><TabsTrigger value="overview">{copy(locale, "نظرة عامة", "Overview")}</TabsTrigger><TabsTrigger value="categories">{copy(locale, "الأقسام", "Categories")} <span className="ms-1 rounded-full bg-muted px-1.5 text-[10px]">{categories.length}</span></TabsTrigger><TabsTrigger value="products">{copy(locale, "المنتجات", "Products")} <span className="ms-1 rounded-full bg-muted px-1.5 text-[10px]">{products.length}</span></TabsTrigger><TabsTrigger value="groups">{copy(locale, "مجموعات الخيارات", "Option groups")}</TabsTrigger><TabsTrigger value="extras">{copy(locale, "الإضافات", "Extras")}</TabsTrigger><TabsTrigger value="design">{copy(locale, "التصميم", "Design")}</TabsTrigger><TabsTrigger value="seasonal">{copy(locale, "القوائم الموسمية", "Seasonal menus")}</TabsTrigger><TabsTrigger value="preview">{copy(locale, "المعاينة", "Preview")}</TabsTrigger></TabsList>
      <TabsContent value="overview" className="mt-0 p-5"><Overview locale={locale} categories={categories} products={products} groups={groups} extras={extras} menus={menus} currency={restaurant.currency} /></TabsContent>
      <TabsContent value="categories" className="mt-0 p-5"><div className="space-y-5"><Toolbar locale={locale} query={query} setQuery={setQuery} action={can("menu.categories.manage") ? <Button size="sm" onClick={() => setEditingCategory({ id: "", menuId: menus.find((m) => m.isDefault)?.id ?? null, nameAr: "", nameEn: "", description: "", imageUrl: "", coverUrl: "", sortOrder: categories.length, isVisible: true, availableFrom: null, availableTo: null, createdAt: "", updatedAt: "", _count: { products: 0 } })}><Plus />{copy(locale, "قسم جديد", "New category")}</Button> : null} /><CategoryTable locale={locale} categories={filteredCategories} canEdit={can("menu.categories.manage")} onEdit={setEditingCategory} /></div></TabsContent>
      <TabsContent value="products" className="mt-0 p-5"><div className="space-y-5"><Toolbar locale={locale} query={query} setQuery={setQuery} action={<div className="flex flex-wrap gap-2">{can("menu.import") ? <form action={importProductsCsvAction} encType="multipart/form-data"><label className="inline-flex h-8 cursor-pointer items-center gap-2 rounded-lg border bg-card px-3 text-xs font-semibold hover:bg-accent"><FileUp />{copy(locale, "استيراد CSV", "Import CSV")}<input type="file" name="file" accept=".csv,text/csv" className="hidden" onChange={(e) => e.currentTarget.form?.requestSubmit()} /></label></form> : null}<a className="inline-flex h-8 items-center gap-2 rounded-lg border bg-card px-3 text-xs font-semibold hover:bg-accent" href={`/api/app/menu/export?type=products`}><FileDown />{copy(locale, "تصدير CSV", "Export CSV")}</a>{can("menu.products.create") ? <Button size="sm" onClick={() => setEditingProduct(newProduct(categories[0]?.id ?? ""))}><Plus />{copy(locale, "منتج جديد", "New product")}</Button> : null}</div>} /><div className="flex flex-wrap gap-2"><Button size="sm" variant={categoryId === "all" ? "subtle" : "outline"} onClick={() => setCategoryId("all")}>{copy(locale, "كل الأقسام", "All categories")}</Button>{categories.map((c) => <Button key={c.id} size="sm" variant={categoryId === c.id ? "subtle" : "outline"} onClick={() => setCategoryId(c.id)}>{locale === "ar" ? c.nameAr : c.nameEn || c.nameAr}</Button>)}</div><ProductTable locale={locale} products={filteredProducts} categories={categories} currency={restaurant.currency} canEdit={can("menu.products.update")} onEdit={setEditingProduct} /></div></TabsContent>
      <TabsContent value="groups" className="mt-0 p-5"><GroupManager locale={locale} groups={groups} canEdit={can("menu.modifiers.manage")} editing={editingGroup} setEditing={setEditingGroup} /></TabsContent>
      <TabsContent value="extras" className="mt-0 p-5"><ExtraManager locale={locale} extras={extras} canEdit={can("menu.extras.manage")} editing={editingExtra} setEditing={setEditingExtra} currency={restaurant.currency} /></TabsContent>
      <TabsContent value="design" className="mt-0 p-5"><ThemeEditor locale={locale} theme={theme} restaurant={restaurant} canEdit={can("menu.themes.manage")} /></TabsContent>
      <TabsContent value="seasonal" className="mt-0 p-5"><SeasonalManager locale={locale} menus={menus} categories={categories} canEdit={can("menu.themes.manage")} editing={editingMenu} setEditing={setEditingMenu} /></TabsContent>
      <TabsContent value="preview" className="mt-0 p-5"><PreviewPanel locale={locale} restaurant={restaurant} theme={theme} /></TabsContent>
    </Tabs></div></Card>
    {editingCategory ? <CategoryEditor locale={locale} category={editingCategory} menus={menus} onClose={() => setEditingCategory(null)} /> : null}
    {editingProduct ? <ProductEditor locale={locale} product={editingProduct} categories={categories} groups={groups} extras={extras} currency={restaurant.currency} onClose={() => setEditingProduct(null)} /> : null}
  </div>;
}

function Toolbar({ locale, query, setQuery, action }: { locale: Locale; query: string; setQuery: (v: string) => void; action?: React.ReactNode }) { return <div className="flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between"><div className="relative max-w-sm flex-1"><Search className="absolute start-3 top-1/2 size-4 -translate-y-1/2 text-muted-foreground" /><Input value={query} onChange={(e) => setQuery(e.target.value)} placeholder={copy(locale, "ابحث…", "Search…")} className="ps-9" /></div><div className="flex flex-wrap gap-2">{action}</div></div>; }
function Overview({ locale, categories, products, groups, extras, menus, currency }: { locale: Locale; categories: Category[]; products: Product[]; groups: Group[]; extras: Extra[]; menus: Menu[]; currency: string }) { const visible = products.filter((p) => p.isVisible).length; return <div className="space-y-6"><div className="grid gap-3 sm:grid-cols-2 xl:grid-cols-4"><MiniStat label={copy(locale, "الأقسام", "Categories")} value={categories.length} icon={<Layers3 />} /><MiniStat label={copy(locale, "المنتجات", "Products")} value={products.length} icon={<UtensilsCrossed />} /><MiniStat label={copy(locale, "المنتجات الظاهرة", "Visible products")} value={`${visible}/${products.length}`} icon={<Eye />} /><MiniStat label={copy(locale, "القوائم", "Menus")} value={menus.length} icon={<Sparkles />} /></div><div className="grid gap-4 lg:grid-cols-2"><Card className="p-5"><SectionHeading title={copy(locale, "جاهزية المنيو", "Menu readiness")} description={copy(locale, "مؤشرات سريعة تساعدك على تجهيز منيو قابل للنشر.", "Quick indicators for a publishable menu.")} /><div className="mt-5 space-y-3">{[[copy(locale,"يوجد قسم واحد على الأقل","At least one category"),categories.length>0],[copy(locale,"يوجد منتج واحد على الأقل","At least one product"),products.length>0],[copy(locale,"كل منتج له قسم أو يبقى في قائمة عامة","Products can be categorized"),products.every((p)=>!!p.categoryId)],[copy(locale,"توجد مجموعات خيارات وإضافات جاهزة","Options and extras are ready"),groups.length>0||extras.length>0]].map(([label,ok])=><div key={String(label)} className="flex items-center gap-3 rounded-xl border p-3"><span className={cn("flex size-7 items-center justify-center rounded-full",ok?"bg-emerald-100 text-emerald-700":"bg-amber-100 text-amber-700")}>{ok?<Check className="size-4"/>:<MoreHorizontal className="size-4"/>}</span><span className="text-sm">{label as string}</span></div>)}</div></Card><Card className="p-5"><SectionHeading title={copy(locale,"آخر القوائم","Menus")} description={copy(locale,"المسودة والقائمة الافتراضية والقوائم الموسمية.","Draft, default, and seasonal menus.")} /><div className="mt-4 space-y-2">{menus.length===0?<EmptyState title={copy(locale,"لا توجد قوائم","No menus yet")} />:menus.map((m)=><div key={m.id} className="flex items-center gap-3 rounded-xl border p-3"><span className="flex size-9 items-center justify-center rounded-lg bg-primary/10 text-primary"><Sparkles className="size-4"/></span><div className="min-w-0 flex-1"><p className="truncate text-sm font-semibold">{m.name}</p><p className="text-xs text-muted-foreground">{m.status} · {m.isDefault?copy(locale,"افتراضية","Default"):copy(locale,"غير افتراضية","Not default")}</p></div><Badge variant={m.status==="ACTIVE"?"success":"outline"}>{m.status}</Badge></div>)}</div></Card></div></div>; }
function MiniStat({ label, value, icon }: { label: string; value: React.ReactNode; icon: React.ReactNode }) { return <div className="rounded-2xl border bg-card p-4"><div className="flex items-center justify-between"><span className="text-xs text-muted-foreground">{label}</span><span className="rounded-lg bg-primary/10 p-2 text-primary">{icon}</span></div><p className="mt-3 text-2xl font-bold">{value}</p></div>; }

function CategoryTable({ locale, categories, canEdit, onEdit }: { locale: Locale; categories: Category[]; canEdit: boolean; onEdit: (c: Category) => void }) {
  const [ordered, setOrdered] = useState(categories);
  const [dragId, setDragId] = useState<string | null>(null);
  const move = (targetId: string) => {
    if (!dragId || dragId === targetId) return;
    const next = [...ordered]; const from = next.findIndex((x) => x.id === dragId); const to = next.findIndex((x) => x.id === targetId);
    if (from < 0 || to < 0) return; const [item] = next.splice(from, 1); next.splice(to, 0, item); setOrdered(next);
    const data = new FormData(); data.set("kind", "category"); data.set("ids", JSON.stringify(next.map((x) => x.id))); void reorderMenuItemsAction(data);
  };
  return ordered.length === 0 ? <EmptyState icon={<Layers3 />} title={copy(locale, "لا توجد أقسام", "No categories yet")} description={copy(locale, "أضف أول قسم لتنظيم المنتجات.", "Create your first category to organize products.")} /> : <div className="overflow-x-auto rounded-xl border"><table className="w-full text-sm"><thead className="bg-muted/50 text-xs text-muted-foreground"><tr><th className="p-3 text-start">{copy(locale, "القسم", "Category")}</th><th className="p-3 text-start">{copy(locale, "المنتجات", "Products")}</th><th className="p-3 text-start">{copy(locale, "الترتيب", "Order")}</th><th className="p-3 text-start">{copy(locale, "الحالة", "Status")}</th><th className="p-3 text-end">{copy(locale, "الإجراءات", "Actions")}</th></tr></thead><tbody>{ordered.map((c, index) => <tr key={c.id} draggable={canEdit} onDragStart={() => setDragId(c.id)} onDragOver={(event) => event.preventDefault()} onDrop={() => move(c.id)} className="border-t cursor-move"><td className="p-3"><div className="flex items-center gap-3">{c.imageUrl ? <img src={c.imageUrl} alt="" className="size-9 rounded-lg object-cover" /> : <span className="flex size-9 items-center justify-center rounded-lg bg-muted"><Layers3 className="size-4" /></span>}<div><p className="font-semibold">{locale === "ar" ? c.nameAr : c.nameEn || c.nameAr}</p><p className="text-xs text-muted-foreground">{c.nameEn && locale === "ar" ? c.nameEn : c.description || "—"}</p></div></div></td><td className="p-3">{c._count.products}</td><td className="p-3">{index + 1}</td><td className="p-3"><Badge variant={c.isVisible ? "success" : "outline"}>{c.isVisible ? copy(locale, "ظاهر", "Visible") : copy(locale, "مخفي", "Hidden")}</Badge></td><td className="p-3"><div className="flex justify-end gap-1">{canEdit ? <><Button size="icon-sm" variant="ghost" onClick={() => onEdit(c)}><Pencil /></Button><ActionForm action={toggleCategoryAction} hidden={{ id: c.id }}><Button size="icon-sm" variant="ghost"><EyeOff /></Button></ActionForm><ActionForm action={duplicateCategoryAction} hidden={{ id: c.id }}><Button size="icon-sm" variant="ghost"><Copy /></Button></ActionForm><ActionForm action={deleteCategoryAction} hidden={{ id: c.id }} confirmText={copy(locale, "حذف القسم؟ ستبقى المنتجات بدون قسم.", "Delete category? Products will become uncategorized.")}><Button size="icon-sm" variant="ghost" className="text-destructive"><Trash2 /></Button></ActionForm></> : null}</div></td></tr>)}</tbody></table><p className="border-t px-3 py-2 text-xs text-muted-foreground">{copy(locale, "اسحب الصفوف لتغيير الترتيب.", "Drag rows to reorder.")}</p></div>;
}
function ProductTable({ locale, products, categories, currency, canEdit, onEdit }: { locale: Locale; products: Product[]; categories: Category[]; currency: string; canEdit: boolean; onEdit: (p: Product) => void }) {
  const [ordered, setOrdered] = useState(products); const [selected, setSelected] = useState<string[]>([]); const [status, setStatus] = useState("all"); const [min, setMin] = useState(""); const [max, setMax] = useState(""); const [dragId, setDragId] = useState<string | null>(null);
  const categoryMap = new Map(categories.map((c) => [c.id, locale === "ar" ? c.nameAr : c.nameEn || c.nameAr]));
  const filtered = ordered.filter((p) => (status === "all" || p.availability === status) && (!min || Number(p.price) >= Number(min)) && (!max || Number(p.price) <= Number(max)));
  const move = (targetId: string) => { if (!dragId || dragId === targetId) return; const next=[...ordered]; const from=next.findIndex((x)=>x.id===dragId); const to=next.findIndex((x)=>x.id===targetId); if(from<0||to<0)return; const [item]=next.splice(from,1); next.splice(to,0,item); setOrdered(next); const data=new FormData(); data.set("kind","product"); data.set("ids",JSON.stringify(next.map((x)=>x.id))); void reorderMenuItemsAction(data); };
  const toggle = (id: string) => setSelected((items) => items.includes(id) ? items.filter((x) => x !== id) : [...items, id]);
  const bulk = (operation: string) => { if (!selected.length) return; const data = new FormData(); data.set("ids", JSON.stringify(selected)); data.set("operation", operation); void bulkProductAction(data); setSelected([]); };
  return filtered.length === 0 ? <EmptyState icon={<UtensilsCrossed />} title={copy(locale, "لا توجد منتجات مطابقة", "No matching products")} description={copy(locale, "غيّر الفلاتر أو أضف منتجاً جديداً.", "Change filters or add a new product.")} /> : <div className="space-y-3"><div className="flex flex-wrap items-center gap-2 rounded-xl border bg-muted/30 p-3"><select value={status} onChange={(e) => setStatus(e.target.value)} className="h-9 rounded-lg border bg-card px-2 text-xs"><option value="all">{copy(locale, "كل الحالات", "All statuses")}</option><option value="ALWAYS">{copy(locale, "متاح", "Available")}</option><option value="SCHEDULED">{copy(locale, "مجدول", "Scheduled")}</option><option value="OUT_OF_STOCK">{copy(locale, "نفد", "Out of stock")}</option><option value="HIDDEN">{copy(locale, "مخفي", "Hidden")}</option></select><Input value={min} onChange={(e)=>setMin(e.target.value)} type="number" placeholder={copy(locale,"السعر من","Min price")} className="h-9 w-28"/><Input value={max} onChange={(e)=>setMax(e.target.value)} type="number" placeholder={copy(locale,"السعر إلى","Max price")} className="h-9 w-28"/>{selected.length ? <><span className="text-xs font-semibold">{selected.length} {copy(locale,"محدد","selected")}</span><Button size="sm" variant="subtle" onClick={()=>bulk("show")}>{copy(locale,"إظهار","Show")}</Button><Button size="sm" variant="outline" onClick={()=>bulk("hide")}>{copy(locale,"إخفاء","Hide")}</Button><Button size="sm" variant="outline" onClick={()=>bulk("out")}>{copy(locale,"نفد","Out")}</Button><Button size="sm" variant="destructive" onClick={()=>bulk("delete")}>{copy(locale,"حذف","Delete")}</Button></> : null}</div><div className="overflow-x-auto rounded-xl border"><table className="w-full text-sm"><thead className="bg-muted/50 text-xs text-muted-foreground"><tr><th className="p-3"><input type="checkbox" checked={selected.length===filtered.length && filtered.length>0} onChange={(e)=>setSelected(e.target.checked?filtered.map((p)=>p.id):[])} /></th><th className="p-3 text-start">{copy(locale,"المنتج","Product")}</th><th className="p-3 text-start">{copy(locale,"القسم","Category")}</th><th className="p-3 text-start">{copy(locale,"السعر","Price")}</th><th className="p-3 text-start">{copy(locale,"التوفر","Availability")}</th><th className="p-3 text-start">{copy(locale,"الخيارات","Options")}</th><th className="p-3 text-end">{copy(locale,"الإجراءات","Actions")}</th></tr></thead><tbody>{filtered.map((p)=><tr key={p.id} draggable={canEdit} onDragStart={()=>setDragId(p.id)} onDragOver={(e)=>e.preventDefault()} onDrop={()=>move(p.id)} className="border-t cursor-move"><td className="p-3"><input type="checkbox" checked={selected.includes(p.id)} onChange={()=>toggle(p.id)} /></td><td className="p-3"><div className="flex items-center gap-3">{p.imageUrl?<img src={p.imageUrl} alt="" className="size-10 rounded-lg object-cover"/>:<span className="flex size-10 items-center justify-center rounded-lg bg-muted"><UtensilsCrossed className="size-4"/></span>}<div><p className="font-semibold">{locale==="ar"?p.nameAr:p.nameEn||p.nameAr}</p><p className="line-clamp-1 max-w-[240px] text-xs text-muted-foreground">{locale==="ar"?p.descriptionAr:p.descriptionEn||p.descriptionAr||"—"}</p></div></div></td><td className="p-3 text-xs">{p.categoryId?categoryMap.get(p.categoryId):copy(locale,"بدون قسم","Uncategorized")}</td><td className="p-3 font-semibold">{money(p.price,currency)}{p.compareAtPrice?<span className="ms-1 text-xs text-muted-foreground line-through">{money(p.compareAtPrice,currency)}</span>:null}</td><td className="p-3"><Badge variant={p.availability==="ALWAYS"&&p.isVisible?"success":p.availability==="OUT_OF_STOCK"?"warning":"outline"}>{p.availability}</Badge></td><td className="p-3 text-xs">{p.modifierGroups.length} / {p.extras.length}</td><td className="p-3"><div className="flex justify-end gap-1">{canEdit?<><Button size="icon-sm" variant="ghost" onClick={()=>onEdit(p)}><Pencil/></Button><ActionForm action={toggleProductAction} hidden={{id:p.id}}><Button size="icon-sm" variant="ghost"><EyeOff/></Button></ActionForm><ActionForm action={duplicateProductAction} hidden={{id:p.id}}><Button size="icon-sm" variant="ghost"><Copy/></Button></ActionForm><ActionForm action={deleteProductAction} hidden={{id:p.id}} confirmText={copy(locale,"حذف المنتج؟ سيتم إخفاؤه مع الحفاظ على سجل الطلبات.","Delete product? It will be hidden while order history is preserved.")}><Button size="icon-sm" variant="ghost" className="text-destructive"><Trash2/></Button></ActionForm></>:null}</div></td></tr>)}</tbody></table><p className="border-t px-3 py-2 text-xs text-muted-foreground">{copy(locale, "اسحب الصفوف لتغيير الترتيب. استخدم التحديد المتعدد لتطبيق إجراء جماعي.", "Drag rows to reorder. Use multi-select for bulk actions.")}</p></div></div>;
}
function CategoryEditor({ locale, category, menus, onClose }: { locale: Locale; category: Category; menus: Menu[]; onClose: () => void }) { return <EditorOverlay title={category.id?copy(locale,"تعديل القسم","Edit category"):copy(locale,"قسم جديد","New category")} onClose={onClose}><form action={saveCategoryAction} className="space-y-4"><input type="hidden" name="id" value={category.id}/><FormField label={copy(locale,"الاسم بالعربية","Arabic name")} required><Input name="nameAr" required defaultValue={category.nameAr}/></FormField><FormField label={copy(locale,"الاسم بالإنجليزية","English name")}><Input name="nameEn" defaultValue={category.nameEn??""}/></FormField><FormField label={copy(locale,"الوصف","Description")}><Textarea name="description" defaultValue={category.description??""}/></FormField><div className="grid gap-3 sm:grid-cols-2"><FormField label={copy(locale,"الصورة URL","Image URL")}><Input name="imageUrl" type="url" defaultValue={category.imageUrl??""}/></FormField><FormField label={copy(locale,"الغلاف URL","Cover URL")}><Input name="coverUrl" type="url" defaultValue={category.coverUrl??""}/></FormField></div><div className="grid gap-3 sm:grid-cols-2"><FormField label={copy(locale,"الترتيب","Order")}><Input name="sortOrder" type="number" defaultValue={category.sortOrder}/></FormField><FormField label={copy(locale,"القائمة","Menu")}><select name="menuId" defaultValue={category.menuId??""} className="h-10 w-full rounded-xl border bg-card px-3 text-sm"><option value="">{copy(locale,"كل القوائم","All menus")}</option>{menus.map(m=><option key={m.id} value={m.id}>{m.name}</option>)}</select></FormField><FormField label={copy(locale,"يظهر من","Visible from")}><Input name="availableFrom" type="datetime-local" defaultValue={category.availableFrom?new Date(category.availableFrom).toISOString().slice(0,16):""}/></FormField><FormField label={copy(locale,"يظهر حتى","Visible until")}><Input name="availableTo" type="datetime-local" defaultValue={category.availableTo?new Date(category.availableTo).toISOString().slice(0,16):""}/></FormField></div><div className="flex items-center gap-2"><input type="checkbox" name="isVisible" defaultChecked={category.isVisible}/><Label>{copy(locale,"إظهار القسم في المنيو العام","Show category publicly")}</Label></div><div className="flex justify-end gap-2"><Button type="button" variant="outline" onClick={onClose}>{copy(locale,"إلغاء","Cancel")}</Button><Button type="submit">{copy(locale,"حفظ القسم","Save category")}</Button></div></form></EditorOverlay>; }

function ProductEditor({ locale, product, categories, groups, extras, currency, onClose }: { locale: Locale; product: Product; categories: Category[]; groups: Group[]; extras: Extra[]; currency: string; onClose: () => void }) { const [selectedGroups,setSelectedGroups]=useState(product.modifierGroups.map(x=>x.groupId)); const [selectedExtras,setSelectedExtras]=useState(product.extras.map(x=>x.extraId)); const toggle=(list:string[],set:(v:string[])=>void,id:string)=>set(list.includes(id)?list.filter(x=>x!==id):[...list,id]); return <EditorOverlay title={product.id?copy(locale,"تعديل المنتج","Edit product"):copy(locale,"منتج جديد","New product")} onClose={onClose} wide>{product.id ? <form action={uploadProductImageAction} encType="multipart/form-data" className="mb-4 flex flex-wrap items-center gap-2 rounded-xl border border-dashed p-3"><input type="hidden" name="productId" value={product.id}/><span className="text-xs text-muted-foreground">{copy(locale,"ارفع صورة PNG أو JPG أو WebP حتى 5MB","Upload PNG, JPG, or WebP up to 5MB")}</span><input name="file" type="file" accept="image/png,image/jpeg,image/webp" required className="max-w-full text-xs"/><Button type="submit" size="sm" variant="outline"><FileUp/>{copy(locale,"رفع الصورة","Upload image")}</Button></form> : null}<form action={saveProductAction} className="space-y-5"><input type="hidden" name="id" value={product.id}/><input type="hidden" name="modifierGroupIds" value={JSON.stringify(selectedGroups)}/><input type="hidden" name="extraIds" value={JSON.stringify(selectedExtras)}/><Tabs defaultValue="basic"><TabsList className="w-full justify-start overflow-x-auto"><TabsTrigger value="basic">{copy(locale,"معلومات أساسية","Basic information")}</TabsTrigger><TabsTrigger value="pricing">{copy(locale,"الأسعار والضرائب","Pricing & tax")}</TabsTrigger><TabsTrigger value="options">{copy(locale,"الأحجام والخيارات","Options & extras")}</TabsTrigger><TabsTrigger value="availability">{copy(locale,"التوفر","Availability")}</TabsTrigger><TabsTrigger value="additional">{copy(locale,"معلومات إضافية","Additional")}</TabsTrigger></TabsList><TabsContent value="basic"><div className="grid gap-4 sm:grid-cols-2"><FormField label={copy(locale,"الاسم بالعربية","Arabic name")} required><Input name="nameAr" required defaultValue={product.nameAr}/></FormField><FormField label={copy(locale,"الاسم بالإنجليزية","English name")}><Input name="nameEn" defaultValue={product.nameEn??""}/></FormField><FormField label={copy(locale,"الوصف بالعربية","Arabic description")} className="sm:col-span-2"><Textarea name="descriptionAr" defaultValue={product.descriptionAr??""}/></FormField><FormField label={copy(locale,"الوصف بالإنجليزية","English description")} className="sm:col-span-2"><Textarea name="descriptionEn" defaultValue={product.descriptionEn??""}/></FormField><FormField label={copy(locale,"القسم","Category")}><select name="categoryId" defaultValue={product.categoryId??""} className="h-10 w-full rounded-xl border bg-card px-3 text-sm"><option value="">{copy(locale,"بدون قسم","Uncategorized")}</option>{categories.map(c=><option key={c.id} value={c.id}>{locale==="ar"?c.nameAr:c.nameEn||c.nameAr}</option>)}</select></FormField><FormField label="SKU"><Input name="sku" defaultValue={product.sku??""}/></FormField><FormField label={copy(locale,"رابط الصورة","Image URL")}><Input name="imageUrl" type="url" defaultValue={product.imageUrl??""}/></FormField></div></TabsContent><TabsContent value="pricing"><div className="grid gap-4 sm:grid-cols-3"><FormField label={`${copy(locale,"السعر","Price")} (${currency})`} required><Input name="price" type="number" min="0" step="0.01" required defaultValue={product.price}/></FormField><FormField label={copy(locale,"السعر قبل الخصم","Compare-at price")}><Input name="compareAtPrice" type="number" min="0" step="0.01" defaultValue={product.compareAtPrice??""}/></FormField><FormField label={copy(locale,"التكلفة","Cost price")}><Input name="costPrice" type="number" min="0" step="0.01" defaultValue={product.costPrice??""}/></FormField><FormField label={copy(locale,"الضريبة %","Tax %")}><Input name="taxRate" type="number" min="0" max="100" step="0.01" defaultValue={product.taxRate}/></FormField><FormField label={copy(locale,"سبب تغيير السعر","Price change reason")}><Input name="priceReason" placeholder={copy(locale,"اختياري للتدقيق","Optional audit note")}/></FormField></div></TabsContent><TabsContent value="options"><div className="grid gap-4 lg:grid-cols-2"><OptionPicker locale={locale} title={copy(locale,"مجموعات الخيارات","Option groups")} items={groups.map(g=>({id:g.id,label:locale==="ar"?g.nameAr:g.nameEn||g.nameAr,meta:`${g.options.length} ${copy(locale,"خيار","options")}`}))} selected={selectedGroups} onToggle={(id)=>toggle(selectedGroups,setSelectedGroups,id)}/><OptionPicker locale={locale} title={copy(locale,"الإضافات المشتركة","Shared extras")} items={extras.map(e=>({id:e.id,label:locale==="ar"?e.nameAr:e.nameEn||e.nameAr,meta:money(e.price,currency)}))} selected={selectedExtras} onToggle={(id)=>toggle(selectedExtras,setSelectedExtras,id)}/></div></TabsContent><TabsContent value="availability"><div className="grid gap-4 sm:grid-cols-3"><FormField label={copy(locale,"الحالة","Availability")}><select name="availability" defaultValue={product.availability} className="h-10 w-full rounded-xl border bg-card px-3 text-sm"><option value="ALWAYS">{copy(locale,"متاح دائماً","Always available")}</option><option value="SCHEDULED">{copy(locale,"مجدول","Scheduled")}</option><option value="OUT_OF_STOCK">{copy(locale,"نفد مؤقتاً","Out of stock")}</option><option value="HIDDEN">{copy(locale,"مخفي","Hidden")}</option></select></FormField><FormField label={copy(locale,"وقت التحضير بالدقائق","Prep minutes")}><Input name="prepMinutes" type="number" min="0" defaultValue={product.prepMinutes}/></FormField><FormField label={copy(locale,"الكمية","Stock quantity")}><Input name="stockQty" type="number" min="0" defaultValue={product.stockQty??""}/></FormField></div><div className="flex flex-wrap gap-5"><label className="flex items-center gap-2 text-sm"><input type="checkbox" name="trackStock" defaultChecked={product.trackStock}/>{copy(locale,"تتبع المخزون","Track stock")}</label><label className="flex items-center gap-2 text-sm"><input type="checkbox" name="isVisible" defaultChecked={product.isVisible}/>{copy(locale,"ظاهر في المنيو","Visible publicly")}</label><label className="flex items-center gap-2 text-sm"><input type="checkbox" name="isFeatured" defaultChecked={product.isFeatured}/>{copy(locale,"منتج مميز","Featured product")}</label></div></TabsContent><TabsContent value="additional"><div className="grid gap-4 sm:grid-cols-2"><FormField label={copy(locale,"المكونات","Ingredients")}><Textarea name="ingredients" defaultValue={product.ingredients??""}/></FormField><FormField label={copy(locale,"الحساسيات (افصل بفواصل)","Allergens (comma separated)")}><Input name="allergens" defaultValue={product.allergens.join(", ")} /><p className="mt-1 text-xs text-muted-foreground">{copy(locale,"يمكنك استخدام JSON أو تعديل الخدمة لمعالجة الفواصل.","Use JSON or extend the action to parse comma-separated values.")}</p></FormField><FormField label={copy(locale,"الوسوم","Tags")}><Input name="tags" defaultValue={product.tags.join(", ")} /></FormField><FormField label={copy(locale,"الترتيب","Order")}><Input name="sortOrder" type="number" min="0" defaultValue={product.sortOrder}/></FormField></div></TabsContent></Tabs><div className="flex flex-wrap justify-end gap-2 border-t pt-4"><Button type="button" variant="outline" onClick={onClose}>{copy(locale,"إلغاء","Cancel")}</Button><Button type="submit" name="publish" value="true">{copy(locale,"حفظ ونشر","Save & publish")}</Button><Button type="submit">{copy(locale,"حفظ كمسودة","Save draft")}</Button></div></form></EditorOverlay>; }

function OptionPicker({ locale, title, items, selected, onToggle }: { locale: Locale; title: string; items: { id: string; label: string; meta: string }[]; selected: string[]; onToggle: (id: string) => void }) { return <div className="rounded-2xl border p-4"><h3 className="font-semibold">{title}</h3><div className="mt-3 space-y-2">{items.length===0?<p className="text-sm text-muted-foreground">{copy(locale,"لا توجد عناصر بعد.","No items yet.")}</p>:items.map(item=><label key={item.id} className="flex cursor-pointer items-center gap-3 rounded-xl border p-3 hover:bg-accent"><input type="checkbox" checked={selected.includes(item.id)} onChange={()=>onToggle(item.id)}/><span className="min-w-0 flex-1"><span className="block text-sm font-medium">{item.label}</span><span className="block text-xs text-muted-foreground">{item.meta}</span></span></label>)}</div></div>; }
function EditorOverlay({ title, onClose, children, wide }: { title: string; onClose: () => void; children: React.ReactNode; wide?: boolean }) { return <div className="fixed inset-0 z-50 flex items-start justify-center overflow-y-auto bg-black/40 p-4"><div className={cn("my-8 w-full rounded-2xl border bg-background p-5 shadow-2xl",wide?"max-w-4xl":"max-w-xl")}><div className="mb-5 flex items-center justify-between gap-4"><h2 className="text-lg font-bold">{title}</h2><Button type="button" variant="ghost" size="icon-sm" onClick={onClose}>×</Button></div>{children}</div></div>; }
function newProduct(categoryId: string): Product { return { id:"",categoryId,nameAr:"",nameEn:"",descriptionAr:"",descriptionEn:"",sku:"",price:"0",compareAtPrice:null,costPrice:null,taxRate:"0",imageUrl:"",calories:null,prepMinutes:15,ingredients:"",allergens:[],tags:[],availability:"ALWAYS",stockQty:null,trackStock:false,isVisible:true,isFeatured:false,sortOrder:0,createdAt:"",updatedAt:"",modifierGroups:[],extras:[] }; }

function GroupManager({ locale, groups, canEdit, editing, setEditing }: { locale: Locale; groups: Group[]; canEdit: boolean; editing: Group | null; setEditing: (g: Group | null) => void }) { const blank: Group={id:"",nameAr:"",nameEn:"",description:"",isRequired:false,minSelect:0,maxSelect:1,isMultiple:false,sortOrder:groups.length,createdAt:"",updatedAt:"",_count:{products:0},options:[]}; return <div className="space-y-5"><SectionHeading title={copy(locale,"مجموعات الخيارات","Option groups")} description={copy(locale,"حدد الخيارات الإلزامية والحد الأدنى والأقصى لكل منتج.","Define required options and min/max selections.")} action={canEdit?<Button size="sm" onClick={()=>setEditing(blank)}><Plus/>{copy(locale,"مجموعة جديدة","New group")}</Button>:null}/><div className="grid gap-3 lg:grid-cols-2">{groups.length===0?<EmptyState icon={<Layers3/>} title={copy(locale,"لا توجد مجموعات خيارات","No option groups yet")}/>:groups.map(g=><Card key={g.id} className="p-4"><div className="flex items-start gap-3"><div className="min-w-0 flex-1"><h3 className="font-semibold">{locale==="ar"?g.nameAr:g.nameEn||g.nameAr}</h3><p className="mt-1 text-xs text-muted-foreground">{g.isRequired?copy(locale,"إلزامي","Required"):copy(locale,"اختياري","Optional")} · {g.minSelect}–{g.maxSelect} · {g._count.products} {copy(locale,"منتج","products")}</p></div>{canEdit?<div className="flex gap-1"><Button size="icon-sm" variant="ghost" onClick={()=>setEditing(g)}><Pencil/></Button><ActionForm action={deleteModifierGroupAction} hidden={{id:g.id}} confirmText={copy(locale,"حذف المجموعة؟","Delete group?")}><Button size="icon-sm" variant="ghost" className="text-destructive"><Trash2/></Button></ActionForm></div>:null}</div><div className="mt-3 flex flex-wrap gap-2">{g.options.map(o=><span key={o.id} className={cn("rounded-full border px-2.5 py-1 text-xs",!o.isAvailable&&"opacity-50 line-through")}>{locale==="ar"?o.nameAr:o.nameEn||o.nameAr}{Number(o.priceDelta)>0?` +${o.priceDelta}`:""}</span>)}</div></Card>)}</div>{editing?<GroupEditor locale={locale} group={editing} onClose={()=>setEditing(null)}/>:null}</div>; }
function GroupEditor({ locale, group, onClose }: { locale: Locale; group: Group; onClose: () => void }) { const [options,setOptions]=useState(group.options.map(o=>({nameAr:o.nameAr,nameEn:o.nameEn??"",priceDelta:Number(o.priceDelta),isDefault:o.isDefault,isAvailable:o.isAvailable,sortOrder:o.sortOrder}))); return <EditorOverlay title={group.id?copy(locale,"تعديل مجموعة","Edit option group"):copy(locale,"مجموعة خيارات جديدة","New option group")} onClose={onClose}><form action={saveModifierGroupAction} className="space-y-4"><input type="hidden" name="id" value={group.id}/><input type="hidden" name="options" value={JSON.stringify(options)}/><div className="grid gap-3 sm:grid-cols-2"><FormField label={copy(locale,"الاسم بالعربية","Arabic name")}><Input required name="nameAr" defaultValue={group.nameAr}/></FormField><FormField label={copy(locale,"الاسم بالإنجليزية","English name")}><Input name="nameEn" defaultValue={group.nameEn??""}/></FormField><FormField label={copy(locale,"الحد الأدنى","Minimum")}><Input name="minSelect" type="number" min="0" defaultValue={group.minSelect}/></FormField><FormField label={copy(locale,"الحد الأقصى","Maximum")}><Input name="maxSelect" type="number" min="1" defaultValue={group.maxSelect}/></FormField></div><FormField label={copy(locale,"الوصف","Description")}><Textarea name="description" defaultValue={group.description??""}/></FormField><div className="flex flex-wrap gap-5 text-sm"><label className="flex items-center gap-2"><input type="checkbox" name="isRequired" defaultChecked={group.isRequired}/>{copy(locale,"إلزامي","Required")}</label><label className="flex items-center gap-2"><input type="checkbox" name="isMultiple" defaultChecked={group.isMultiple}/>{copy(locale,"اختيارات متعددة","Multiple selection")}</label></div><div className="rounded-xl border p-3"><div className="mb-3 flex items-center justify-between"><h3 className="font-semibold">{copy(locale,"الخيارات","Options")}</h3><Button type="button" size="sm" variant="outline" onClick={()=>setOptions([...options,{nameAr:"",nameEn:"",priceDelta:0,isDefault:false,isAvailable:true,sortOrder:options.length}])}><Plus/>{copy(locale,"إضافة خيار","Add option")}</Button></div><div className="space-y-2">{options.map((o,index)=><div key={index} className="grid gap-2 sm:grid-cols-[1fr_1fr_110px_auto]"><Input placeholder={copy(locale,"عربي","Arabic")} value={o.nameAr} onChange={e=>setOptions(options.map((x,i)=>i===index?{...x,nameAr:e.target.value}:x))}/><Input placeholder={copy(locale,"English","English")} value={o.nameEn} onChange={e=>setOptions(options.map((x,i)=>i===index?{...x,nameEn:e.target.value}:x))}/><Input type="number" step="0.01" placeholder={copy(locale,"السعر","Price")} value={o.priceDelta} onChange={e=>setOptions(options.map((x,i)=>i===index?{...x,priceDelta:Number(e.target.value)}:x))}/><Button type="button" variant="ghost" size="icon-sm" onClick={()=>setOptions(options.filter((_,i)=>i!==index))}><Trash2/></Button></div>)}</div></div><div className="flex justify-end gap-2"><Button type="button" variant="outline" onClick={onClose}>{copy(locale,"إلغاء","Cancel")}</Button><Button type="submit">{copy(locale,"حفظ المجموعة","Save group")}</Button></div></form></EditorOverlay>; }

function ExtraManager({ locale, extras, canEdit, editing, setEditing, currency }: { locale: Locale; extras: Extra[]; canEdit: boolean; editing: Extra | null; setEditing: (e: Extra | null) => void; currency: string }) { const blank: Extra={id:"",nameAr:"",nameEn:"",price:"0",isActive:true,sortOrder:extras.length,createdAt:"",_count:{products:0}}; return <div className="space-y-5"><SectionHeading title={copy(locale,"الإضافات المشتركة","Shared extras")} description={copy(locale,"إضافات قابلة لإعادة الاستخدام والربط بعدة منتجات.","Reusable extras that can be linked to many products.")} action={canEdit?<Button size="sm" onClick={()=>setEditing(blank)}><Plus/>{copy(locale,"إضافة جديدة","New extra")}</Button>:null}/><div className="overflow-x-auto rounded-xl border"><table className="w-full text-sm"><thead className="bg-muted/50 text-xs text-muted-foreground"><tr><th className="p-3 text-start">{copy(locale,"الإضافة","Extra")}</th><th className="p-3 text-start">{copy(locale,"السعر","Price")}</th><th className="p-3 text-start">{copy(locale,"المنتجات المرتبطة","Linked products")}</th><th className="p-3 text-start">{copy(locale,"الحالة","Status")}</th><th className="p-3 text-end">{copy(locale,"الإجراءات","Actions")}</th></tr></thead><tbody>{extras.map(e=><tr key={e.id} className="border-t"><td className="p-3 font-semibold">{locale==="ar"?e.nameAr:e.nameEn||e.nameAr}</td><td className="p-3">{money(e.price,currency)}</td><td className="p-3">{e._count.products}</td><td className="p-3"><Badge variant={e.isActive?"success":"outline"}>{e.isActive?copy(locale,"نشط","Active"):copy(locale,"متوقف","Paused")}</Badge></td><td className="p-3"><div className="flex justify-end gap-1">{canEdit?<><Button size="icon-sm" variant="ghost" onClick={()=>setEditing(e)}><Pencil/></Button><ActionForm action={toggleExtraAction} hidden={{id:e.id}}><Button size="icon-sm" variant="ghost"><EyeOff/></Button></ActionForm><ActionForm action={deleteExtraAction} hidden={{id:e.id}} confirmText={copy(locale,"حذف الإضافة؟","Delete extra?")}><Button size="icon-sm" variant="ghost" className="text-destructive"><Trash2/></Button></ActionForm></>:null}</div></td></tr>)}</tbody></table></div>{editing?<EditorOverlay title={editing.id?copy(locale,"تعديل الإضافة","Edit extra"):copy(locale,"إضافة جديدة","New extra")} onClose={()=>setEditing(null)}><form action={saveExtraAction} className="space-y-4"><input type="hidden" name="id" value={editing.id}/><FormField label={copy(locale,"الاسم بالعربية","Arabic name")}><Input name="nameAr" required defaultValue={editing.nameAr}/></FormField><FormField label={copy(locale,"الاسم بالإنجليزية","English name")}><Input name="nameEn" defaultValue={editing.nameEn??""}/></FormField><FormField label={`${copy(locale,"السعر","Price")} (${currency})`}><Input name="price" type="number" min="0" step="0.01" defaultValue={editing.price}/></FormField><label className="flex items-center gap-2 text-sm"><input type="checkbox" name="isActive" defaultChecked={editing.isActive}/>{copy(locale,"نشطة","Active")}</label><div className="flex justify-end gap-2"><Button type="button" variant="outline" onClick={()=>setEditing(null)}>{copy(locale,"إلغاء","Cancel")}</Button><Button type="submit">{copy(locale,"حفظ","Save")}</Button></div></form></EditorOverlay>:null}</div>; }

function ThemeEditor({ locale, theme, restaurant, canEdit }: { locale: Locale; theme: Record<string, string | boolean>; restaurant: { primaryColor: string; secondaryColor: string; fontFamily: string; menuLayout: string }; canEdit: boolean }) { return <div className="space-y-5"><SectionHeading title={copy(locale,"مصمم المنيو","Menu designer")} description={copy(locale,"خصص الهوية والألوان والبطاقات والهيدر والفوتر مع معاينة فورية.","Customize identity, colors, cards, header, and footer with a live preview.")} /><div className="grid gap-5 lg:grid-cols-[1fr_320px]"><form action={saveMenuThemeAction} className="space-y-5 rounded-2xl border p-5"><div className="grid gap-4 sm:grid-cols-2"><FormField label={copy(locale,"الثيم","Theme")}><select name="template" defaultValue={String(theme.template??"classic")} className="h-10 w-full rounded-xl border bg-card px-3 text-sm"><option value="classic">Classic</option><option value="modern">Modern</option><option value="cafe">Cafe</option><option value="minimal">Minimal</option></select></FormField><FormField label={copy(locale,"تخطيط الصفحة","Page layout")}><select name="layout" defaultValue={String(theme.layout??restaurant.menuLayout)} className="h-10 w-full rounded-xl border bg-card px-3 text-sm"><option value="grid">{copy(locale,"شبكة","Grid")}</option><option value="list">{copy(locale,"قائمة","List")}</option><option value="editorial">Editorial</option></select></FormField><FormField label={copy(locale,"اللون الأساسي","Primary color")}><Input name="primaryColor" type="color" defaultValue={String(theme.primaryColor??restaurant.primaryColor)}/></FormField><FormField label={copy(locale,"اللون الثانوي","Secondary color")}><Input name="secondaryColor" type="color" defaultValue={String(theme.secondaryColor??restaurant.secondaryColor)}/></FormField><FormField label={copy(locale,"الخط","Font")}><select name="fontFamily" defaultValue={String(theme.fontFamily??restaurant.fontFamily)} className="h-10 w-full rounded-xl border bg-card px-3 text-sm"><option>IBM Plex Sans Arabic</option><option>Cairo</option><option>Tajawal</option><option>Inter</option><option>Noto Sans Arabic</option></select></FormField><FormField label={copy(locale,"شكل البطاقات","Card style")}><select name="cardStyle" defaultValue={String(theme.cardStyle??"soft")} className="h-10 w-full rounded-xl border bg-card px-3 text-sm"><option value="soft">{copy(locale,"ناعم","Soft")}</option><option value="flat">{copy(locale,"مسطح","Flat")}</option><option value="bordered">{copy(locale,"محدد","Bordered")}</option></select></FormField><FormField label={copy(locale,"حجم الصور","Image size")}><select name="imageSize" defaultValue={String(theme.imageSize??"medium")} className="h-10 w-full rounded-xl border bg-card px-3 text-sm"><option value="small">{copy(locale,"صغير","Small")}</option><option value="medium">{copy(locale,"متوسط","Medium")}</option><option value="large">{copy(locale,"كبير","Large")}</option></select></FormField><FormField label={copy(locale,"شكل الأقسام","Category style")}><select name="categoryStyle" defaultValue={String(theme.categoryStyle??"pills")} className="h-10 w-full rounded-xl border bg-card px-3 text-sm"><option value="pills">Pills</option><option value="tabs">Tabs</option><option value="cards">Cards</option></select></FormField><FormField label={copy(locale,"نص الفوتر بالعربية","Arabic footer")}><Input name="footerAr" defaultValue={String(theme.footerAr??"")}/></FormField><FormField label={copy(locale,"نص الفوتر بالإنجليزية","English footer")}><Input name="footerEn" defaultValue={String(theme.footerEn??"")}/></FormField></div><div className="flex flex-wrap gap-5 text-sm"><label className="flex items-center gap-2"><input type="checkbox" name="showCover" defaultChecked={theme.showCover!==false}/>{copy(locale,"إظهار الغلاف","Show cover")}</label><label className="flex items-center gap-2"><input type="checkbox" name="showLogo" defaultChecked={theme.showLogo!==false}/>{copy(locale,"إظهار الشعار","Show logo")}</label><label className="flex items-center gap-2"><input type="checkbox" name="showFooter" defaultChecked={theme.showFooter!==false}/>{copy(locale,"إظهار الفوتر","Show footer")}</label></div><div className="flex flex-wrap gap-2"><Button type="submit" disabled={!canEdit}><Palette/>{copy(locale,"حفظ ونشر التصميم","Save & publish design")}</Button><Button type="submit" formAction={resetMenuThemeAction} variant="outline" disabled={!canEdit}>{copy(locale,"استعادة الافتراضي","Restore default")}</Button></div></form><Card className="overflow-hidden"><div className="border-b p-4"><p className="text-xs font-semibold text-muted-foreground">{copy(locale,"معاينة الهاتف","Mobile preview")}</p></div><div className="m-4 overflow-hidden rounded-2xl border bg-muted/30" style={{fontFamily:String(theme.fontFamily??restaurant.fontFamily)}}><div className="h-24" style={{background:String(theme.primaryColor??restaurant.primaryColor)}}/><div className="space-y-3 p-4"><div className="h-4 w-1/2 rounded bg-foreground/10"/><div className="h-3 w-3/4 rounded bg-foreground/10"/><div className="grid grid-cols-2 gap-2"><div className="h-28 rounded-xl bg-card shadow-sm"/><div className="h-28 rounded-xl bg-card shadow-sm"/></div><div className="h-3 w-full rounded bg-foreground/10"/></div></div></Card></div></div>; }

function SeasonalManager({ locale, menus, categories, canEdit, editing, setEditing }: { locale: Locale; menus: Menu[]; categories: Category[]; canEdit: boolean; editing: Menu | null; setEditing: (m: Menu | null) => void }) { const blank:Menu={id:"",name:"",description:"",type:"SEASONAL",status:"DRAFT",isDefault:false,startsAt:null,endsAt:null,createdAt:"",updatedAt:"",_count:{schedules:0}}; return <div className="space-y-5"><SectionHeading title={copy(locale,"القوائم الموسمية","Seasonal menus")} description={copy(locale,"أنشئ قوائم خاصة بالمواسم وجدول تاريخ بدايتها ونهايتها.","Create seasonal menus and schedule their active date range.")} action={canEdit?<Button size="sm" onClick={()=>setEditing(blank)}><Plus/>{copy(locale,"قائمة جديدة","New menu")}</Button>:null}/><div className="grid gap-3 lg:grid-cols-2">{menus.map(m=><Card key={m.id} className="p-4"><div className="flex items-start gap-3"><div className="min-w-0 flex-1"><h3 className="font-semibold">{m.name}</h3><p className="mt-1 text-xs text-muted-foreground">{m.description||copy(locale,"بدون وصف","No description")}</p><p className="mt-2 text-xs">{m.startsAt?new Date(m.startsAt).toLocaleDateString(locale):"—"} → {m.endsAt?new Date(m.endsAt).toLocaleDateString(locale):"∞"}</p></div><Badge variant={m.status==="ACTIVE"?"success":"outline"}>{m.status}</Badge></div><div className="mt-4 flex flex-wrap gap-2">{canEdit?<><Button size="sm" variant="outline" onClick={()=>setEditing(m)}><Pencil/>{copy(locale,"تعديل","Edit")}</Button><ActionForm action={duplicateMenuAction} hidden={{id:m.id}}><Button size="sm" variant="outline"><Copy/>{copy(locale,"نسخ","Duplicate")}</Button></ActionForm><ActionForm action={setMenuStatusAction} hidden={{id:m.id,status:m.status==="ACTIVE"?"DRAFT":"ACTIVE"}}><Button size="sm" variant={m.status==="ACTIVE"?"outline":"subtle"}>{m.status==="ACTIVE"?copy(locale,"تعطيل","Disable"):copy(locale,"تفعيل ونشر","Activate")}</Button></ActionForm></>:null}</div></Card>)}</div>{editing?<EditorOverlay title={editing.id?copy(locale,"تعديل القائمة","Edit menu"):copy(locale,"قائمة موسمية جديدة","New seasonal menu")} onClose={()=>setEditing(null)}><form action={saveMenuAction} className="space-y-4"><input type="hidden" name="id" value={editing.id}/><FormField label={copy(locale,"اسم القائمة","Menu name")}><Input required name="name" defaultValue={editing.name}/></FormField><FormField label={copy(locale,"الوصف","Description")}><Textarea name="description" defaultValue={editing.description??""}/></FormField><div className="grid gap-3 sm:grid-cols-2"><FormField label={copy(locale,"تاريخ البداية","Start date")}><Input name="startsAt" type="date" defaultValue={editing.startsAt?editing.startsAt.slice(0,10):""}/></FormField><FormField label={copy(locale,"تاريخ النهاية","End date")}><Input name="endsAt" type="date" defaultValue={editing.endsAt?editing.endsAt.slice(0,10):""}/></FormField></div><div className="flex items-center gap-2"><input type="checkbox" name="isDefault" defaultChecked={editing.isDefault}/><Label>{copy(locale,"القائمة الافتراضية","Default menu")}</Label></div><input type="hidden" name="type" value="SEASONAL"/><input type="hidden" name="status" value={editing.status}/><div className="flex justify-end gap-2"><Button type="button" variant="outline" onClick={()=>setEditing(null)}>{copy(locale,"إلغاء","Cancel")}</Button><Button type="submit">{copy(locale,"حفظ القائمة","Save menu")}</Button></div></form></EditorOverlay>:null}</div>; }
function PreviewPanel({ locale, restaurant, theme }: { locale: Locale; restaurant: { slug: string; name: string }; theme: Record<string,string|boolean> }) { const link=`${typeof window!=="undefined"?window.location.origin:""}/r/${restaurant.slug}`; return <div className="space-y-5"><SectionHeading title={copy(locale,"معاينة المنيو","Menu preview")} description={copy(locale,"هذه المعاينة تستخدم الرابط العام الحقيقي للمنيو.","This preview uses the real public menu URL.")} action={<Button asChild><Link href={`/r/${restaurant.slug}`} target="_blank"><ExternalLink/>{copy(locale,"فتح في نافذة جديدة","Open in new tab")}</Link></Button>}/><div className="grid gap-5 lg:grid-cols-[minmax(0,1fr)_320px]"><Card className="min-h-[520px] overflow-hidden"><div className="flex items-center justify-between border-b bg-muted/30 p-3 text-xs"><span>{copy(locale,"معاينة سطح المكتب","Desktop preview")}</span><span className="rounded-full bg-emerald-100 px-2 py-1 text-emerald-700">{copy(locale,"منشور من قاعدة البيانات","Live from database")}</span></div><iframe title="menu-preview" src={`/r/${restaurant.slug}`} className="h-[620px] w-full border-0" /></Card><Card className="h-fit p-5"><h3 className="font-semibold">{copy(locale,"مشاركة المنيو","Share menu")}</h3><p className="mt-2 break-all rounded-xl bg-muted p-3 text-xs" dir="ltr">{link}</p><div className="mt-3 flex flex-wrap gap-2"><Button size="sm" variant="outline" onClick={()=>navigator.clipboard?.writeText(link)}><Copy/>{copy(locale,"نسخ الرابط","Copy link")}</Button><Button size="sm" variant="outline" onClick={()=>window.print()}><FileDown/>{copy(locale,"طباعة / PDF","Print / PDF")}</Button><Button asChild size="sm" variant="outline"><a href={`/api/app/menu/qr?slug=${encodeURIComponent(restaurant.slug)}`} download><FileDown/>{copy(locale,"تنزيل QR","Download QR")}</a></Button></div><div className="mt-5 rounded-xl border border-dashed p-4 text-center"><Sparkles className="mx-auto size-6 text-primary"/><p className="mt-2 text-sm font-semibold">{copy(locale,"QR المنيو العام جاهز","Public menu QR is ready")}</p><p className="mt-1 text-xs text-muted-foreground">{copy(locale,"يتم توليده من الرابط العام الحالي للمطعم.","Generated from the restaurant's current public URL.")}</p></div></Card></div></div>; }
